package com.example.familytree.service;

import com.example.familytree.domain.DomainModels.*;
import com.example.familytree.repo.Repositories.*;
import org.junit.jupiter.api.*;
import org.mockito.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class FamilyServiceTest {
 AccessService access=mock(AccessService.class); TreeRepo trees=mock(TreeRepo.class); MemberRepo members=mock(MemberRepo.class); RelationRepo relations=mock(RelationRepo.class);
 FamilyService service; Map<Long,Member> memberMap; List<Relationship> rels; long nextMember;
 varAuth auth=new varAuth();
 static class varAuth extends UsernamePasswordAuthenticationToken { varAuth(){super("owner","n/a",List.of());} }
 @BeforeEach void setup(){service=new FamilyService(access,trees,members,relations);when(relations.findByTreeId(1L)).thenAnswer(i->new ArrayList<>(rels));memberMap=new HashMap<>();rels=new ArrayList<>();nextMember=10;when(members.save(any())).thenAnswer(i->{Member m=i.getArgument(0);if(m.getId()==null)m.setId(nextMember++);memberMap.put(m.getId(),m);return m;});when(members.findByIdAndTreeIdAndDeletedFalse(anyLong(),eq(1L))).thenAnswer(i->Optional.ofNullable(memberMap.get(i.<Long>getArgument(0))).filter(x->!x.isDeleted()));when(relations.save(any())).thenAnswer(i->{Relationship r=i.getArgument(0);r.setId((long)rels.size()+1);rels.add(r);return r;});when(relations.findByTreeIdAndFromMemberId(eq(1L),anyLong())).thenAnswer(i->rels.stream().filter(r->r.getFromMemberId().equals(i.getArgument(1))).toList());when(relations.findByTreeIdAndToMemberId(eq(1L),anyLong())).thenAnswer(i->rels.stream().filter(r->r.getToMemberId().equals(i.getArgument(1))).toList());when(relations.touching(eq(1L),anyLong())).thenAnswer(i->rels.stream().filter(r->r.getFromMemberId().equals(i.getArgument(1))||r.getToMemberId().equals(i.getArgument(1))).toList());when(relations.existsByTreeIdAndFromMemberIdAndToMemberIdAndRelationType(anyLong(),anyLong(),anyLong(),any())).thenAnswer(i->rels.stream().anyMatch(r->r.getFromMemberId().equals(i.getArgument(1))&&r.getToMemberId().equals(i.getArgument(2))&&r.getRelationType()==i.getArgument(3)));}
 private Member member(long id,String name){var m=new Member(1L,name,Gender.UNKNOWN);m.setId(id);memberMap.put(id,m);return m;}
 @Test void rejectsParentCycle(){member(1,"祖父");member(2,"父亲");member(3,"孩子");service.addRelation(1L,1L,2L,RelationType.PARENT,auth);service.addRelation(1L,2L,3L,RelationType.PARENT,auth);assertThrows(AccessService.ConflictException.class,()->service.addRelation(1L,3L,1L,RelationType.PARENT,auth));}
 @Test void refusesDeletingMemberWithDescendants(){member(1,"父亲");member(2,"孩子");service.addRelation(1L,1L,2L,RelationType.PARENT,auth);assertThrows(AccessService.ConflictException.class,()->service.delete(1L,1L,auth));assertFalse(memberMap.get(1L).isDeleted());}
 @Test void removesOnlySelectedRelationAndKeepsMembers(){member(1,"父亲");member(2,"孩子");member(3,"另一位家人");var removed=service.addRelation(1L,1L,2L,RelationType.PARENT,auth);var kept=service.addRelation(1L,1L,3L,RelationType.PARENT,auth);when(relations.findByIdAndTreeId(removed.getId(),1L)).thenReturn(Optional.of(removed));doAnswer(i->{rels.remove(i.getArgument(0));return null;}).when(relations).delete(any(Relationship.class));service.removeRelation(1L,removed.getId(),auth);verify(access,atLeastOnce()).requireEdit(1L,auth);assertEquals(List.of(kept),rels);assertEquals(3,memberMap.size());assertFalse(memberMap.values().stream().anyMatch(Member::isDeleted));verify(members,never()).delete(any());}
 @Test void refusesRemovingRelationFromAnotherTree(){when(relations.findByIdAndTreeId(7L,2L)).thenReturn(Optional.empty());assertThrows(AccessService.NotFoundException.class,()->service.removeRelation(2L,7L,auth));verify(relations,never()).delete(any());}
 @Test void refusesRemovingMissingRelation(){when(relations.findByIdAndTreeId(999L,1L)).thenReturn(Optional.empty());assertThrows(AccessService.NotFoundException.class,()->service.removeRelation(1L,999L,auth));verify(relations,never()).delete(any());}
 @Test void viewerCannotRemoveRelations(){doThrow(new org.springframework.security.access.AccessDeniedException("无编辑权限")).when(access).requireEdit(1L,auth);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.removeRelation(1L,1L,auth));verify(relations,never()).findByIdAndTreeId(anyLong(),anyLong());verify(relations,never()).delete(any());}
 @Test void parentRelationAlsoLinksExistingSpouseWithoutCreatingMembers(){member(1,"父亲");member(2,"配偶");member(3,"子女");service.addRelation(1L,1L,2L,RelationType.SPOUSE,auth);service.addRelation(1L,1L,3L,RelationType.PARENT,auth);assertTrue(rels.stream().anyMatch(r->r.getFromMemberId()==2L&&r.getToMemberId()==3L&&r.getRelationType()==RelationType.PARENT));assertEquals(3,rels.size());verify(members,never()).save(any());}
 @Test void laterMarriageSynchronizesChildrenInBothDirections(){for(long i=1;i<=4;i++)member(i,"成员"+i);service.addRelation(1L,1L,3L,RelationType.PARENT,auth);service.addRelation(1L,2L,4L,RelationType.PARENT,auth);service.addRelation(1L,2L,1L,RelationType.SPOUSE,auth);assertEquals(5,rels.size());assertTrue(rels.stream().anyMatch(r->r.getFromMemberId()==1L&&r.getToMemberId()==4L&&r.getRelationType()==RelationType.PARENT));assertTrue(rels.stream().anyMatch(r->r.getFromMemberId()==2L&&r.getToMemberId()==3L&&r.getRelationType()==RelationType.PARENT));verify(members,never()).save(any());}
 @Test void synchronizationSkipsExistingParentEdges(){for(long i=1;i<=3;i++)member(i,"成员"+i);service.addRelation(1L,1L,3L,RelationType.PARENT,auth);service.addRelation(1L,2L,3L,RelationType.PARENT,auth);service.addRelation(1L,1L,2L,RelationType.SPOUSE,auth);assertEquals(3,rels.size());assertThrows(AccessService.ConflictException.class,()->service.addRelation(1L,1L,2L,RelationType.SPOUSE,auth));assertEquals(3,rels.size());}
 @Test void spouseChildSyncValidatesAllEdgesBeforeSaving(){for(long i=1;i<=3;i++)member(i,"成员"+i);service.addRelation(1L,1L,2L,RelationType.SPOUSE,auth);service.addRelation(1L,3L,2L,RelationType.PARENT,auth);int before=rels.size();assertThrows(AccessService.ConflictException.class,()->service.addRelation(1L,1L,3L,RelationType.PARENT,auth));assertEquals(before,rels.size());assertFalse(rels.stream().anyMatch(r->r.getFromMemberId()==1L&&r.getToMemberId()==3L));}
 @Test void laterMarriageWithAncestorCannotLeavePartialSpouseLink(){for(long i=1;i<=3;i++)member(i,"成员"+i);service.addRelation(1L,1L,2L,RelationType.PARENT,auth);service.addRelation(1L,2L,3L,RelationType.PARENT,auth);assertThrows(AccessService.ConflictException.class,()->service.addRelation(1L,1L,3L,RelationType.SPOUSE,auth));assertEquals(2,rels.size());assertFalse(rels.stream().anyMatch(r->r.getRelationType()==RelationType.SPOUSE));}
 @Test void relationshipRequiresExistingMembers(){member(1,"已存在成员");assertThrows(AccessService.NotFoundException.class,()->service.addRelation(1L,1L,999L,RelationType.PARENT,auth));assertTrue(rels.isEmpty());verify(members,never()).save(any());}
 @Test void siblingRelationDoesNotCreateMembersOrParentLinks(){member(1,"甲");member(2,"乙");service.addRelation(1L,1L,2L,RelationType.SIBLING,auth);assertEquals(1,rels.size());verify(members,never()).save(any());}
 @Test void findsBidirectionalKinshipPath(){member(1,"祖父");member(2,"父亲");member(3,"孩子");service.addRelation(1L,1L,2L,RelationType.PARENT,auth);service.addRelation(1L,2L,3L,RelationType.PARENT,auth);var path=service.path(1L,3L,1L,auth);assertEquals(2,path.size());assertEquals("PARENT",path.get(0).relation());assertEquals(1L,path.get(1).memberId());}
}
